		cfg.DomainSlugs = make(map[string]string)
	}
	if slug := cfg.DomainSlugs[host]; slug != "" {
		return slug, nil
	}

	slug := generateDomainSlug(host, cfg.DomainSlugs)
	cfg.DomainSlugs[host] = slug
